    aiReviewContent: `『패싱』은 1920년대 미국을 배경으로 흑인 혈통을 숨긴 채 살아가는 클레어와 자신의 정체성을 지키며 살아가는 아이린의 재회를 통해 인종과 계급의 문제를 섬세하게 그려냅니다. 짧고 절제된 문장 속에 긴장감 있게 쌓이는 심리 묘사가 인상적이며, 정체성이란 무엇인가에 대한 묵직한 질문을 남깁니다. 할렘 르네상스 시기 문학을 새롭게 발견하고 싶은 독자에게 권합니다.`,
    description: `
    넬라 라슨의 『패싱』은 인종과 계급, 정체성이라는 문제를 한 여성의 선택과 관계를 통해 날카롭게 그려 낸 작품이다. 1920년대 미국을 배경으로 하는 이 소설은 흑인으로 태어났지만 백인으로 살아갈 수 있는 외모를 가진 인물들이 서로 다른 삶을 선택하면서 벌어지는 긴장과 갈등을 중심으로 전개된다. 주인공 아이린은 자신의 정체성을 숨기지 않고 안정적인 가정과 공동체 안에서 살아가지만, 어린 시절 친구였던 클레어는 백인 사회에 자신의 흑인 혈통을 숨긴 채 완전히 다른 삶을 살아간다. 두 사람의 재회는 서로가 선택한 삶의 차이를 선명하게 드러내며, 아이린이 애써 외면해 온 욕망과 불안을 흔들어 놓는다. 라슨은 인종이라는 사회적 경계가 개인의 삶과 인간관계에 어떻게 작용하는지를 직접적으로 설명하기보다 인물들의 시선과 침묵, 불안한 감정을 통해 섬세하게 보여 준다. 특히 자신의 정체성을 감추는 행위가 개인에게 자유를 가져다주는 동시에 언제든 삶을 위협할 수 있는 위험이 될 수 있다는 점을 긴장감 있게 다룬다. 『패싱』은 결국 타인의 시선 속에서 만들어지는 정체성과 스스로 믿고 싶은 자신의 모습 사이에서 인간이 어떤 선택을 하게 되는지를 묻는 작품이다.
  `,

  editorReview: `
    넬라 라슨은 할렘 르네상스 시기의 미국 문학을 대표하는 작가 가운데 한 사람으로, 짧은 생애 동안 인종과 성별, 계급의 문제를 섬세하게 탐구한 작품을 남겼다. 특히 『패싱』은 당시 미국 사회에서 인종적 정체성이 개인의 사회적 위치와 삶의 가능성을 얼마나 크게 좌우했는지를 보여 주는 작품으로 평가된다. 라슨은 인물들의 행동을 단순히 선악의 문제로 판단하지 않고, 각자가 처한 사회적 조건과 욕망을 세밀하게 묘사한다. 그 결과 독자는 아이린과 클레어 가운데 어느 한 사람의 선택만을 바라보기보다 두 인물이 서로 다른 방식으로 살아남고자 했던 이유를 함께 살펴보게 된다.

    작품의 제목인 ‘패싱’은 자신의 인종적 배경을 숨기고 다른 인종으로 받아들여지는 행위를 의미한다. 그러나 소설 속에서 패싱은 단순히 신분이나 외모를 바꾸는 행위에 머물지 않고, 자신이 누구인지 그리고 다른 사람에게 어떻게 보이고 싶은지를 둘러싼 복잡한 문제로 확장된다. 라슨은 이러한 설정을 통해 인종적 경계가 개인의 내면에까지 영향을 미치는 과정을 보여 주며, 사회가 만들어 낸 정체성의 기준에 대해 질문한다. 짧고 절제된 문장 속에서 인물들의 심리와 관계를 긴장감 있게 쌓아 올린다는 점 또한 이 작품의 중요한 특징이다.
  `,

  authorInfo: `
    넬라 라슨은 1891년 미국 시카고에서 태어난 미국의 소설가이다. 덴마크계 어머니와 서인도계 아버지를 둔 혼혈 가정에서 성장했으며, 어린 시절부터 자신의 인종적 배경과 사회적 위치에 대해 복잡한 경험을 했다. 간호사와 도서관 사서로 일한 경험을 거친 뒤 문학 활동을 시작했으며, 1920년대 할렘 르네상스의 흐름 속에서 작품을 발표하며 작가로서 주목받았다. 그의 작품은 흑인 여성의 삶과 인종적 정체성, 성별과 계급에 따른 사회적 제약을 주요하게 다룬다.

    대표작으로는 『퀵샌드』와 『패싱』이 있으며, 두 작품 모두 사회적 경계 안에서 자신의 삶을 만들어 가야 하는 여성 인물들의 내면을 중심으로 이야기를 전개한다. 특히 『패싱』에서는 인종적 정체성을 둘러싼 선택과 욕망, 불안이 인물들의 관계를 어떻게 변화시키는지를 세밀하게 묘사했다. 라슨은 1929년 『패싱』으로 구겐하임 펠로십을 받았지만 이후 문단에서 점차 모습을 감추었고, 오랫동안 작품 활동을 하지 않았다.

    넬라 라슨의 작품은 생전에는 제한적으로 알려졌지만 이후 미국 문학과 흑인 여성 문학에 대한 연구가 활발해지면서 다시 주목받았다. 특히 『패싱』은 인종과 정체성이라는 문제를 개인의 심리와 인간관계의 차원에서 다룬 작품으로 오늘날까지 꾸준히 읽히고 있다. 1964년 뉴욕에서 세상을 떠났으며, 비교적 적은 수의 작품만을 남겼지만 미국 문학사에서 중요한 작가로 재평가되고 있다.
  `
