    aiReviewTitle: `현재를 온전히 살아가는 법을 일깨우는 산문시`,
    aiReviewContent: `『지상의 양식』은 정해진 도덕과 관습에서 벗어나 삶을 감각으로 직접 경험할 것을 권하는 앙드레 지드의 산문 작품입니다. 여행과 자연, 사랑에 대한 자유로운 문장들이 읽는 이의 감각을 깨우며, 지금 이 순간을 어떻게 살아가고 있는지 돌아보게 합니다. 삶의 태도를 다시 점검하고 싶은 독자에게 신선한 자극을 주는 책입니다.`,
    description: `
      앙드레 지드의 『지상의 양식』은 삶을 대하는 태도와 감각의 회복을 이야기하는 산문 작품이다. 지드는 정해진 도덕과 관습, 사회가 요구하는 규범에 자신을 맞추기보다 눈앞에 펼쳐진 세계를 직접 경험하고 자신의 감각으로 삶을 받아들일 것을 강조한다. 작품 속 화자는 여행과 자연, 음식과 사랑, 예술과 인간관계 등 다양한 경험을 통해 삶이 가진 아름다움과 기쁨을 발견한다. 특히 현재의 순간을 충분히 살아가는 일과 스스로 원하는 것을 선택하는 태도를 중요하게 다루며, 삶을 지나치게 억압하는 금욕적 가치관에 대해 끊임없이 질문한다. 그러나 『지상의 양식』이 단순히 쾌락만을 추구하는 삶을 이야기하는 것은 아니다. 지드는 삶을 직접 경험하고 자신의 욕망과 감정을 솔직하게 마주하는 과정에서 인간이 더욱 자유로운 존재가 될 수 있다고 바라본다. 자연과 여행에서 얻은 감각적인 인상과 사색을 자유로운 문장으로 풀어낸 이 작품은 독자에게 자신이 지금 어떤 방식으로 삶을 살아가고 있는지를 되돌아보게 한다.
    `,
    editorReview: `
      앙드레 지드의 『지상의 양식』은 20세기 초 프랑스 문학에서 개인의 자유와 삶의 감각을 적극적으로 탐구한 작품으로 손꼽힌다. 소설처럼 하나의 사건을 중심으로 이야기가 진행되기보다는 산문과 시적인 문장, 사색과 독백이 어우러지는 독특한 형식을 통해 삶에 대한 작가의 생각을 전달한다. 지드는 사회와 종교, 도덕이 개인에게 요구하는 절대적인 기준을 의심하면서 스스로 경험하고 판단하는 인간의 중요성을 이야기한다. 이러한 태도는 당시의 전통적인 가치관에 익숙했던 독자들에게 새로운 삶의 가능성을 제시하는 것이기도 했다.

      작품 전체를 관통하는 핵심에는 ‘현재의 삶을 어떻게 살아갈 것인가’라는 질문이 놓여 있다. 지드는 먼 미래를 위해 현재의 삶을 희생하기보다 지금 자신에게 주어진 순간과 세계를 온몸으로 경험하는 태도를 강조한다. 자연과 여행, 사랑과 욕망에 대한 감각적인 묘사는 이러한 사상을 구체적인 경험으로 전달하며, 독자가 자신의 삶을 능동적으로 바라보도록 이끈다. 『지상의 양식』은 이후 지드 문학의 중요한 출발점이 되었으며, 자유로운 개인과 자기 발견이라는 주제를 탐구한 작품으로 오늘날까지 읽히고 있다.
    `,
    authorInfo: `
      앙드레 지드는 1869년 프랑스 파리에서 태어난 작가이다. 어린 시절부터 문학과 종교에 깊은 관심을 보였으며, 청년기에 상징주의 문학의 영향을 받으면서 본격적으로 작품 활동을 시작했다. 그는 자신의 내면과 개인의 자유, 종교와 도덕, 인간의 욕망과 책임 같은 문제를 끊임없이 탐구하며 프랑스 현대문학의 중요한 작가로 자리 잡았다. 특정한 문학적 경향에 머무르기보다 소설과 산문, 일기, 비평 등 다양한 형식을 통해 자신의 사상과 경험을 작품에 담아냈다.

      대표작으로는 『지상의 양식』을 비롯해 『좁은 문』, 『전원 교향악』, 『위폐범들』 등이 있다. 그의 작품에서는 사회가 정해 놓은 규범과 개인의 자유 사이에서 갈등하는 인물들이 자주 등장하며, 자신에게 주어진 삶을 스스로 선택하고 책임지는 문제를 중요하게 다룬다. 또한 여행과 자연에 대한 경험을 문학적 소재로 적극적으로 활용하면서 인간이 기존의 관습에서 벗어나 새로운 삶의 가능성을 발견하는 과정을 보여 주었다.

      지드는 문학 활동뿐 아니라 당대의 사회적 문제와 정치적 현실에도 관심을 가지고 자신의 생각을 적극적으로 표현했다. 특히 자신의 경험과 사상을 숨기지 않고 작품과 일기를 통해 기록하면서 20세기 프랑스 문학에 큰 영향을 남겼다. 이러한 문학적 성취를 인정받아 1947년 노벨문학상을 수상했으며, 자유와 개인의 내면을 탐구한 작가로 문학사에 남아 있다.
    `
