    authorInfo: `
      밀란 쿤데라는 1929년 체코슬로바키아 브르노에서 태어난 소설가이자 시인, 극작가이다. 프라하에서 성장했으며 음악과 문학을 공부한 뒤 작품 활동을 시작했다. 초기에는 체코어로 작품을 발표했으며, 체코슬로바키아의 정치적·사회적 현실과 개인의 삶이 충돌하는 문제에 관심을 보였다. 이후 프랑스로 이주해 생활했으며, 후기 작품에서는 프랑스어로도 소설을 집필했다.

      대표작으로는 『농담』, 『참을 수 없는 존재의 가벼움』, 『불멸』, 『느림』 등이 있다. 그의 소설은 사랑과 인간관계, 기억과 망각, 역사와 정치 같은 다양한 주제를 다루면서도 철학적인 사유와 소설적 이야기를 결합하는 것이 특징이다. 특히 작품 속에서 작가가 직접 이야기에 개입해 인물과 사건에 대한 생각을 펼치는 방식은 쿤데라 문학의 독특한 특징으로 꼽힌다. 개인의 삶을 거대한 역사적 상황과 연결하면서도 결국 그 안에서 살아가는 한 인간의 감정과 선택을 세밀하게 바라본다.

      쿤데라는 체코 출신 작가로서 유럽의 역사적 변화와 전체주의 체제의 경험을 작품에 담았으며, 망명 이후에는 고국과 언어, 기억과 정체성이라는 문제 역시 중요한 문학적 관심사가 되었다. 그의 작품은 소설이 단순히 이야기를 전달하는 형식을 넘어 인간과 세계에 대해 질문하는 사유의 공간이 될 수 있음을 보여 준다. 2023년 프랑스 파리에서 세상을 떠났으며, 20세기와 21세기 유럽 문학을 대표하는 작가 가운데 한 사람으로 기억되고 있다.
    `
