    aiReviewContent: `『가치의 모든 것』은 우리가 당연하게 받아들이는 경제적 가치가 어떻게 만들어지는지를 파헤치는 마리아나 마추카토의 역작입니다. 생산적 활동과 가치 추출을 구분하는 시각이 신선하며, 정부와 시장의 관계를 새롭게 바라보게 합니다. 경제를 숫자가 아닌 구조로 이해하고 싶은 독자에게 유익한 통찰을 제공합니다.`,
    description: `
      마리아나 마추카토의 『가치의 모든 것』은 우리가 경제적 가치라고 부르는 것이 어떻게 만들어지고, 누가 그 가치를 인정받는지를 다시 생각하게 하는 경제학 책이다. 현대 사회에서는 기업가나 금융기관, 노동자 등이 만들어 내는 부가가치가 시장에서 자연스럽게 결정되는 것처럼 보이지만, 마추카토는 무엇이 가치 있는 활동인지에 대한 기준 자체가 사회적으로 만들어져 왔다고 이야기한다. 특히 생산적인 활동과 단순히 기존의 부를 이전하거나 추출하는 활동을 구분하지 않을 경우 경제 성장의 성과가 실제로 어디에서 만들어졌는지를 제대로 이해하기 어렵다고 지적한다. 금융과 기업 활동, 정부의 역할을 살펴보면서 시장과 국가를 서로 대립하는 존재로만 바라보는 관점에도 질문을 던진다. 정부의 공공투자와 정책이 새로운 산업과 기술의 발전에 중요한 기반을 제공할 수 있다는 점 역시 책에서 중요하게 다루어진다. 이를 통해 경제 성장을 단순히 시장의 결과로 받아들이기보다 어떤 활동이 사회에 실질적인 가치를 만들어 내는지 살펴볼 필요가 있음을 보여 준다. 『가치의 모든 것』은 돈의 흐름과 경제성장의 결과만을 바라보는 데서 벗어나 가치가 만들어지는 과정 자체를 질문하며, 우리가 당연하게 받아들였던 경제의 기준을 다시 생각하게 하는 책이다.
    `,
    editorReview: `
      『가치의 모든 것』에서 마리아나 마추카토가 가장 중요하게 제기하는 문제는 ‘가치란 무엇인가’라는 질문이다. 경제학에서는 생산과 소비, 이윤과 가격을 통해 경제활동을 설명하는 경우가 많지만, 가격이 높다는 사실만으로 그것이 사회적으로 높은 가치를 만들어 낸다고 말할 수 있는지는 별개의 문제다. 마추카토는 이러한 차이에 주목하면서 경제활동을 바라보는 기존의 기준이 어떤 방식으로 형성되었는지를 역사적으로 살펴본다. 특히 가치를 만들어 내는 활동과 이미 만들어진 가치를 가져가는 활동을 구분하는 것이 경제를 이해하는 데 중요하다고 강조한다.

      이 책은 기업과 금융, 정부의 관계를 새롭게 바라볼 수 있는 관점을 제시한다. 정부는 시장이 실패했을 때 뒤늦게 개입하는 존재에 그치는 것이 아니라 장기적인 연구개발과 공공투자를 통해 새로운 시장과 산업의 형성에 참여할 수 있다는 것이 마추카토의 주요한 주장이다. 따라서 경제성장을 평가할 때 단순히 국내총생산이나 기업의 이윤과 같은 수치만을 바라보는 것이 아니라 어떤 활동이 사회 전체에 지속적인 가치를 만들어 내고 있는지를 함께 살펴볼 필요가 있다. 『가치의 모든 것』은 경제에서 사용하는 ‘가치’라는 개념을 다시 정의하고, 시장과 정부의 역할에 대해 생각할 수 있는 출발점을 제공한다.
    `,
    authorInfo: `
      마리아나 마추카토는 이탈리아계 미국인 경제학자로, 혁신과 경제성장 과정에서 국가와 시장의 역할을 연구해 온 학자이다. 런던대학교 유니버시티 칼리지 런던의 혁신 및 공공가치 경제학 교수로 활동했으며, 혁신과 기업가정신, 공공정책을 연결하는 연구를 진행해 왔다. 특히 국가가 시장의 실패를 보완하는 수동적인 역할만 하는 것이 아니라 새로운 기술과 산업의 발전을 적극적으로 이끌 수 있다는 관점으로 잘 알려져 있다.

      대표적인 저서로 『기업가형 국가』와 『가치의 모든 것』 등이 있으며, 그의 연구는 정부의 연구개발 투자와 혁신 생태계의 관계를 설명하는 데 초점을 맞춘다. 마추카토는 스마트폰과 인터넷, 생명공학 등 현대의 혁신적인 기술이 순수하게 민간기업의 활동만으로 만들어진 것이 아니라 장기간에 걸친 공공 부문의 연구와 투자가 중요한 기반이 되었다고 분석한다. 이를 바탕으로 국가가 혁신의 위험을 함께 부담하면서도 그 과정에서 만들어진 가치가 사회 전체에 어떻게 돌아가야 하는지를 질문한다.

      마추카토는 경제학의 역할이 이미 존재하는 시장을 설명하는 데만 머무르지 않고 사회가 어떤 방향으로 나아갈 것인지에 대한 논의에도 참여해야 한다고 주장한다. 그의 연구는 경제적 가치와 공공가치의 관계, 혁신과 불평등, 국가와 기업의 관계 등 현대 경제가 마주한 문제를 다루고 있다. 이러한 연구를 통해 경제성장을 숫자로만 평가하기보다 가치가 만들어지는 과정과 그 결과가 사회에 어떻게 분배되는지를 함께 바라보는 관점을 제시하고 있다.
    `
