    aiReviewContent: `『글로벌 그린 뉴딜』은 화석연료 중심 산업구조의 한계를 지적하며 재생에너지와 디지털 기술이 결합한 새로운 인프라의 필요성을 역설합니다. 환경 문제를 경제 전환의 계기로 바라보는 시각이 인상적이며, 지속가능한 미래 사회의 구체적인 모습을 그려볼 수 있습니다. 기후와 경제를 함께 고민하는 독자에게 실질적인 통찰을 줍니다.`,
    description: `
      제러미 리프킨의 『글로벌 그린 뉴딜』은 기후변화와 에너지 전환이라는 거대한 문제를 새로운 경제 시스템을 구축하는 계기로 바라보는 책이다. 리프킨은 화석연료를 중심으로 성장해 온 기존 산업 구조가 기후위기와 환경 문제를 심화시키는 동시에 경제적·사회적 불평등을 만들어 왔다고 분석한다. 그는 이러한 문제를 해결하기 위해 재생에너지와 디지털 기술, 사물인터넷, 분산형 에너지 시스템을 결합한 새로운 산업 인프라가 필요하다고 주장한다. 특히 태양광과 풍력 등 재생 가능한 에너지를 지역에서 생산하고 공유하는 구조를 통해 에너지 생산 방식 자체가 변화할 수 있다고 설명한다. 이러한 에너지 전환은 단순히 기존의 에너지원을 바꾸는 데 그치지 않고 건물과 교통, 제조업, 통신 등 사회 전체의 생산과 소비 방식을 변화시키는 과정으로 이어진다. 리프킨은 새로운 인프라에 대한 대규모 투자가 일자리와 산업을 만들어 내면서 동시에 탄소 배출을 줄이는 효과를 가져올 수 있다고 본다. 『글로벌 그린 뉴딜』은 기후변화를 해결해야 할 위기로만 바라보지 않고 경제와 산업의 구조를 전환할 수 있는 중요한 계기로 바라보면서 지속 가능한 미래 사회가 어떤 모습이어야 하는지 구체적으로 질문하는 책이다.
    `,
    editorReview: `
      『글로벌 그린 뉴딜』에서 제러미 리프킨은 기후위기와 경제위기를 서로 분리된 문제로 바라보지 않는다. 화석연료에 의존해 성장해 온 산업 시스템이 환경적 한계를 드러내고 있는 만큼, 새로운 에너지와 인프라를 중심으로 경제 구조 자체를 바꿀 필요가 있다는 것이 책의 핵심적인 문제의식이다. 리프킨은 이를 위해 재생에너지의 확대뿐 아니라 디지털 통신 기술과 전력망, 교통 시스템, 건축 환경이 서로 연결되는 새로운 인프라의 구축을 강조한다. 이러한 변화가 이루어진다면 에너지를 소수의 거대 생산자가 독점하는 방식에서 벗어나 보다 분산된 생산과 공유가 가능한 경제 구조로 이동할 수 있다고 설명한다.

      책에서 말하는 그린 뉴딜은 환경정책에만 한정된 개념이 아니다. 에너지와 산업, 교통, 건축, 노동시장 등 사회 전반의 구조를 동시에 변화시키는 장기적인 경제 전환을 의미한다. 따라서 기후변화에 대응하는 과정에서 새로운 산업과 일자리를 만들어 내고, 경제적 기회를 보다 넓게 분배하는 것 역시 중요한 과제가 된다. 『글로벌 그린 뉴딜』은 기후위기에 대응하기 위해 어떤 기술을 사용할 것인가를 넘어 어떤 경제 시스템과 사회 구조를 만들어 갈 것인가라는 질문까지 확장해 생각하게 한다.
    `,
    authorInfo: `
      제러미 리프킨은 미국의 경제·사회 이론가이자 작가로, 기술 변화와 에너지 체계, 경제 구조의 관계를 오랫동안 연구해 온 인물이다. 그는 산업사회가 사용하는 에너지와 커뮤니케이션 기술의 변화가 사회의 생산 방식과 조직 구조에도 큰 영향을 미친다고 바라보며, 새로운 기술이 가져올 경제적·사회적 변화에 대한 전망을 여러 저서를 통해 제시해 왔다. 특히 에너지 전환과 기후변화, 디지털 기술이 미래 사회에 미치는 영향에 지속적인 관심을 가져왔다.

      대표적인 저서로 『엔트로피』, 『소유의 종말』, 『공감의 시대』, 『3차 산업혁명』, 『글로벌 그린 뉴딜』 등이 있다. 『3차 산업혁명』에서는 인터넷과 재생에너지, 분산형 전력망이 결합하면서 새로운 경제 인프라가 형성될 가능성을 제시했으며, 이후 『글로벌 그린 뉴딜』에서는 기후변화와 경제 전환이라는 문제를 보다 직접적으로 다루었다. 그의 저서들은 기술 발전을 단순한 기술적 변화로 보지 않고 사회의 경제 구조와 인간의 생활 방식까지 변화시키는 과정으로 해석한다.

      리프킨은 지속 가능한 에너지 체계로의 전환이 환경을 보호하는 것뿐 아니라 새로운 경제활동과 산업을 만들어 내는 과정이 될 수 있다고 강조한다. 또한 정부와 기업, 시민사회가 장기적인 전환 과정에서 어떤 역할을 맡아야 하는지에 대해서도 지속적으로 논의해 왔다. 그의 연구는 기후변화와 에너지 전환을 경제와 산업의 관점에서 함께 바라보게 하며, 미래 사회가 어떤 방식으로 에너지와 자원을 생산하고 사용하는지에 대한 논의를 확장해 왔다.
    `
