    aiReviewContent: `『밀회』는 사라진 아이를 찾아 병원에 들어간 남자가 점차 이해할 수 없는 세계로 빨려 들어가는 과정을 그린 아베 코보의 작품입니다. 익숙한 공간이 낯설게 변해가는 서술이 독특한 긴장감을 자아내며, 현대인의 고립과 소외를 상징적으로 보여줍니다. 실험적인 서사와 철학적 물음을 즐기는 독자에게 잘 맞는 작품입니다.`,
    description: `
      아베 코보의 『밀회』는 낯선 공간에 갇힌 인간이 현실과 비현실의 경계를 경험하면서 자신의 존재와 타인과의 관계를 다시 바라보게 되는 작품이다. 어느 날 갑작스럽게 사라진 아이를 찾기 위해 병원으로 들어간 남자는 그곳에서 일상적인 공간이라고 생각했던 병원이 점차 이해하기 어려운 규칙과 질서를 가진 세계로 변해 가는 모습을 마주한다. 사람들은 자신의 목적과 기억을 명확하게 설명하지 못한 채 낯선 상황에 적응하고, 주인공 역시 자신이 무엇을 찾고 있는지조차 불분명한 상태에서 공간을 헤매게 된다. 현실적인 장소와 비현실적인 사건이 자연스럽게 뒤섞이면서 독자는 무엇이 실제이고 무엇이 환상인지 쉽게 판단할 수 없게 된다. 아베 코보는 이러한 불확실성을 통해 현대 사회에서 개인이 느끼는 고립과 소외, 자신의 존재를 확인하기 어려운 상황을 표현한다. 익숙한 공간이 낯선 장소로 바뀌고 평범했던 인간관계가 이해할 수 없는 관계로 변해 가는 과정은 현대인이 경험하는 불안과 단절을 더욱 선명하게 드러낸다. 『밀회』는 하나의 사건을 해결하는 이야기에 머무르지 않고 현실의 틈에서 길을 잃은 인간이 자신과 세계의 관계를 어떻게 이해할 수 있는지를 질문하는 작품이다.
    `,
    editorReview: `
      아베 코보의 작품에서 자주 발견되는 특징은 현실적인 공간과 비현실적인 상황을 결합하여 인간의 존재 조건을 낯설게 보여 주는 것이다. 『밀회』 역시 병원이라는 익숙한 장소를 출발점으로 삼지만, 이야기가 진행될수록 그 공간은 기존의 상식과 규칙이 통하지 않는 세계로 변화한다. 인물들은 자신이 처한 상황을 완전히 이해하지 못한 채 움직이며, 독자 역시 인물들과 함께 사건의 의미를 찾아가게 된다. 이러한 서술 방식은 현실을 명확하게 설명하기보다 불확실한 상태 자체를 경험하게 만든다는 점에서 아베 코보 문학의 특징을 잘 보여 준다.

      작품에서 공간은 단순히 사건이 벌어지는 배경이 아니라 인간의 심리와 존재를 드러내는 중요한 장치로 기능한다. 익숙한 장소가 낯설게 변하면서 인물은 자신이 어디에 있으며 무엇을 해야 하는지 끊임없이 확인해야 하는 상황에 놓인다. 그 과정에서 인간이 사회와 타인에게 의존하면서도 동시에 타인과 완전히 소통할 수 없는 존재라는 사실이 드러난다. 『밀회』는 현실과 환상의 경계를 흐리는 독특한 서사를 통해 인간의 고립과 불안을 표현하며, 우리가 당연하게 믿고 있는 현실의 구조에 대해서도 질문을 던진다.
    `,
    authorInfo: `
      아베 코보는 1924년 일본 도쿄에서 태어난 소설가이자 극작가이다. 어린 시절 만주에서 성장했으며, 도쿄대학교 의학부에 진학했지만 의사가 되기보다 문학 활동에 관심을 두고 작품을 발표하기 시작했다. 전후 일본 문학의 새로운 흐름 속에서 기존의 사실주의적인 소설 형식에서 벗어나 인간의 고립과 소외, 정체성의 문제를 독특한 상상력으로 표현했다. 그는 소설뿐 아니라 희곡과 연극 활동에도 관심을 가지고 다양한 방식으로 자신의 작품 세계를 확장했다.

      대표작으로는 『모래의 여자』, 『타인의 얼굴』, 『상자 남자』 등이 있다. 그의 작품에는 자신이 누구인지 확인하기 어려운 인물이나 일상적인 공간에서 갑자기 낯선 상황에 빠지는 인물이 자주 등장한다. 이러한 설정을 통해 현대 사회에서 개인이 느끼는 고립과 불안, 타인과의 단절을 표현했으며, 현실과 환상의 경계를 자유롭게 넘나드는 독특한 문학 세계를 구축했다. 특히 『모래의 여자』에서는 끝없이 모래를 퍼내야 하는 공간에 갇힌 남자를 통해 인간이 사회와 현실의 구조에서 벗어나기 어려운 상황을 상징적으로 보여 주었다.

      아베 코보는 전후 일본 문학에서 실험적인 형식과 독창적인 상상력을 보여 준 작가로 평가받으며 일본 밖에서도 작품이 널리 소개되었다. 그의 작품은 인간의 존재와 정체성을 개인의 심리뿐 아니라 사회와 공간의 관계 속에서 바라본다는 특징을 가지고 있다. 1993년 세상을 떠났으며, 현실을 낯설게 바라보는 독특한 서술과 철학적인 문제의식을 통해 일본 현대문학에 뚜렷한 흔적을 남겼다.
    `
