    aiReviewContent: `『릿터 61호』는 소설과 시, 에세이, 비평을 한 권에 담아 동시대 한국문학의 다양한 목소리를 보여주는 문학잡지입니다. 여러 작가의 서로 다른 문체와 감각을 비교하며 읽는 재미가 있으며, 문학의 현재를 가까이에서 느낄 수 있습니다. 새로운 작가와 작품을 발견하고 싶은 독자에게 유익한 한 권입니다.`,
    description: `
      『릿터 61호』는 민음사가 격월로 발행하는 문학 잡지로, 동시대 한국문학의 다양한 작품과 작가들의 목소리를 한 권에 담아낸다. 소설과 시, 에세이, 비평 등 여러 장르를 함께 구성하여 하나의 작품을 깊이 읽는 것뿐 아니라 현재 문학이 어떤 주제와 감각을 향해 나아가고 있는지를 폭넓게 살펴볼 수 있도록 한다. 매 호 새로운 작가와 작품을 소개하는 동시에 이미 활동하고 있는 작가들의 새로운 글을 함께 수록하면서 한국문학의 현재를 다양한 방향에서 바라본다. 문학 작품 자체뿐 아니라 작가의 생각과 창작 과정, 작품을 둘러싼 비평적 시선까지 함께 다룬다는 점에서 일반적인 단행본과는 다른 읽기의 경험을 제공한다. 특히 하나의 주제에만 집중하기보다 여러 작품과 목소리를 병렬적으로 배치하여 독자가 서로 다른 문학적 세계를 비교하며 읽을 수 있도록 구성한다. 『릿터 61호』 역시 2026년 하반기 한국문학의 흐름 속에서 동시대 작가들이 어떤 이야기를 만들어 내고 있는지 살펴볼 수 있는 문학적 기록으로 기능한다.
    `,
    editorReview: `
      『릿터』는 새로운 문학 작품을 소개하는 데 그치지 않고 동시대 문학을 둘러싼 다양한 생각과 논의를 함께 담아내는 문학 잡지이다. 한 권 안에 여러 작가와 장르의 글이 수록되기 때문에 독자는 서로 다른 문체와 주제, 창작 방식이 한 시대 안에서 어떻게 공존하고 있는지를 자연스럽게 살펴볼 수 있다. 신작 소설과 시를 읽는 즐거움과 함께 작가 인터뷰와 에세이, 비평 등을 통해 작품을 보다 다양한 관점에서 바라볼 수 있다는 것도 『릿터』의 특징이다. 이러한 구성은 개별 작품을 독립적으로 읽는 것에서 한 걸음 더 나아가 작품과 작가, 그리고 문학을 둘러싼 시대적 맥락까지 함께 생각하게 한다.

      문학 잡지는 한 시대의 문학적 풍경을 기록한다는 점에서도 의미가 있다. 시간이 지나면 하나의 작품으로 기억되는 문학도 처음 발표될 당시에는 다른 작품들과 함께 특정한 시대의 흐름 속에 존재하기 때문이다. 『릿터 61호』는 다양한 작가의 글을 한데 모아 현재 한국문학이 가진 여러 방향성을 보여 주며, 독자에게 아직 완성된 하나의 흐름으로 정리되지 않은 동시대 문학을 직접 만날 기회를 제공한다. 새로운 작품을 발견하고 서로 다른 작가의 시선을 비교하며 읽고 싶은 독자에게 문학의 현재를 가까이에서 경험할 수 있는 한 권이다.
    `,
    authorInfo: `
      『릿터』는 민음사에서 발행하는 격월간 문학 잡지로, 한국문학을 중심으로 동시대의 다양한 문학적 목소리를 소개해 왔다. 한 명의 작가가 쓴 단일 작품을 수록하는 일반적인 단행본과 달리 여러 작가의 소설과 시, 에세이, 비평 및 인터뷰 등을 함께 구성하여 현재 문학의 다양한 모습을 보여 주는 것을 특징으로 한다. 이를 통해 이미 잘 알려진 작가뿐 아니라 새로운 작가와 작품을 독자에게 소개하고, 문학 작품을 둘러싼 여러 관점과 이야기를 함께 전달한다.

      『릿터』는 정기적으로 새로운 호를 발행하면서 매 호마다 동시대 작가들의 신작과 다양한 문학적 기획을 선보인다. 문학 작품뿐 아니라 작가의 창작 과정과 문학에 대한 생각을 접할 수 있는 글을 함께 구성함으로써 독자가 작품을 보다 입체적으로 이해할 수 있도록 한다. 이러한 잡지의 특성 때문에 각각의 호는 발행 당시 한국문학의 관심사와 작가들의 새로운 시도를 확인할 수 있는 기록으로도 읽을 수 있다.

      『릿터 61호』 역시 여러 작가와 작품을 한 권에 담아 2026년의 동시대 문학을 다양한 각도에서 바라볼 수 있도록 구성된 문학 잡지이다. 하나의 작품에 집중하기보다 여러 목소리를 차례로 만나고 서로 다른 문학적 감각을 비교해 볼 수 있다는 점에서 문학을 폭넓게 읽고 싶은 독자에게 의미 있는 읽기 경험을 제공한다.
    `
