    aiReviewTitle: `어른이 된다는 것의 두려움과 외로움을 그린 청춘의 초상`,
    aiReviewContent: `『호밀밭의 파수꾼』은 학교에서 퇴학당한 소년 홀든이 며칠간 뉴욕을 떠돌며 겪는 방황을 통해 성장의 불안을 섬세하게 그려냅니다. 거친 언어 뒤에 감춰진 순수함과 동생 피비를 향한 애정이 깊은 여운을 남기며, 청소년기의 보편적 감정을 강렬하게 포착합니다. 성장소설의 대표작을 경험하고 싶은 독자에게 강력히 추천합니다.`,
    description: `
      제롬 데이비드 샐린저의 『호밀밭의 파수꾼』은 학교에서 퇴학당한 열여섯 살 소년 홀든 콜필드가 집으로 돌아가기 전 며칠 동안 뉴욕을 떠돌며 겪는 일을 그린 성장소설이다. 홀든은 자신을 둘러싼 어른들의 세계를 위선적이고 가식적인 것으로 바라보며 학교와 사회가 요구하는 규칙에 쉽게 적응하지 못한다. 학교에서 쫓겨난 뒤 곧바로 집으로 돌아가지 않고 여러 사람을 만나며 도시를 떠돌지만, 그 과정에서 자신이 진정으로 원하는 것이 무엇인지 명확하게 설명하지 못한 채 계속해서 혼란을 경험한다. 어린 시절의 순수함을 잃고 싶지 않아 하면서도 이미 성장의 과정에 들어선 홀든의 모습은 청소년기의 불안과 외로움을 생생하게 보여 준다. 특히 어린 동생 피비와의 관계는 홀든이 세상의 ‘가식’을 비판하는 것만큼이나 순수한 관계와 사랑을 중요하게 여기고 있음을 드러낸다. 홀든이 상상하는 ‘호밀밭의 파수꾼’은 아이들이 절벽 아래로 떨어지지 않도록 지켜 주는 존재로, 어린아이의 순수함을 지켜 주고 싶어 하는 그의 마음을 상징한다. 『호밀밭의 파수꾼』은 한 소년이 방황하는 며칠을 통해 성장의 두려움과 외로움, 상실과 순수함에 대한 갈망을 보여 주며, 어른이 된다는 것이 무엇인지 생각하게 하는 작품이다.
    `,
    editorReview: `
      『호밀밭의 파수꾼』은 청소년기의 불안과 반항을 주제로 하지만 단순히 반항적인 소년의 이야기에 머무르지 않는다. 홀든은 자신이 싫어하는 것에 대해서는 매우 분명한 태도를 보이지만 정작 자신이 어떤 삶을 원하는지에 대해서는 쉽게 답하지 못한다. 그가 끊임없이 다른 사람을 ‘가식적’이라고 판단하는 모습은 세상에 대한 비판인 동시에 자신이 받아들이기 어려운 현실로부터 스스로를 보호하는 방식이기도 하다. 따라서 홀든의 방황은 단순한 일탈이라기보다 어린 시절과 성인 세계 사이에서 자신의 자리를 찾지 못한 한 인간의 내면적인 방황으로 읽을 수 있다.

      작품의 가장 인상적인 부분 가운데 하나는 홀든의 거친 언어와 행동 뒤에 감춰진 섬세한 감정이다. 그는 사람들에게 냉소적인 태도를 보이면서도 자신이 아끼는 사람에게는 깊은 애정을 가지고 있으며, 특히 어린아이의 순수함을 잃게 하고 싶지 않아 한다. 그러나 성장 자체를 멈출 수는 없기 때문에 홀든이 원하는 세계와 현실 사이에는 계속해서 간극이 발생한다. 샐린저는 이러한 모순을 완전히 해결하지 않은 채 홀든의 목소리를 따라가며 성장의 과정이 반드시 명확한 답을 얻는 과정은 아니라는 점을 보여 준다. 작품이 오랫동안 청소년 문학의 대표작으로 읽혀 온 이유 역시 이러한 불안과 혼란을 특정한 나이의 문제에 한정하지 않고 인간이 성장하면서 겪는 보편적인 감정으로 표현했기 때문이다.
    `,
    authorInfo: `
      제롬 데이비드 샐린저는 1919년 미국 뉴욕에서 태어난 소설가이다. 뉴욕에서 성장했으며 여러 학교를 다닌 뒤 대학에서 공부했지만 학업을 끝까지 이어 가지는 않았다. 제2차 세계대전 당시 군인으로 복무했으며 유럽 전선에 참여한 경험을 했다. 전쟁 이후 본격적으로 문학 활동을 이어 갔으며, 단편소설을 여러 잡지에 발표하면서 작가로서 이름을 알리기 시작했다.

      대표작인 『호밀밭의 파수꾼』은 1951년에 출간되었으며 발표 이후 젊은 독자들에게 큰 반향을 일으켰다. 작품의 주인공 홀든 콜필드는 기존의 가치와 사회적 규범에 쉽게 적응하지 못하는 청소년의 모습을 보여 주며, 당시 문학에서 비교적 솔직하게 표현되지 않았던 청소년기의 불안과 혼란을 강렬한 목소리로 표현했다. 이후 샐린저는 『아홉 가지 이야기』와 글래스 가족을 중심으로 한 여러 단편을 발표하면서 인간의 내면과 가족관계, 정신적 성장에 대한 관심을 이어 갔다.

      샐린저는 작품 활동이 알려진 것에 비해 언론과 대중의 관심을 피하며 사적인 생활을 중요하게 여긴 작가로도 잘 알려져 있다. 특히 『호밀밭의 파수꾼』의 성공 이후에도 작품 외적인 활동을 크게 늘리지 않았으며, 후기에는 대중에게 거의 모습을 드러내지 않았다. 2010년 미국 뉴햄프셔에서 세상을 떠났으며, 『호밀밭의 파수꾼』은 청소년기의 성장과 방황을 다룬 현대 미국문학의 대표적인 작품으로 오늘날까지 널리 읽히고 있다.
    `
