    aiReviewContent: `『호아』는 거대한 사건 대신 일상 속 관계의 미묘한 변화와 감정을 섬세하게 포착하는 한국소설입니다. 인물들의 침묵과 머뭇거림 속에 담긴 복잡한 마음이 잔잔한 여운을 남기며, 타인을 이해한다는 것의 어려움을 다시 생각하게 합니다. 조용하지만 깊은 울림을 주는 이야기를 좋아하는 독자에게 추천합니다.`,
    description: `
      강진아의 『호아』는 평범해 보이는 일상 속에서 관계의 변화와 감정의 결을 세밀하게 포착하는 한국소설이다. 인물들은 거대한 사건이나 극적인 상황보다는 자신이 살아가는 현실 속에서 마주하는 사람과 기억, 말과 침묵을 통해 조금씩 흔들린다. 가까운 사람과의 관계에서 생겨나는 미묘한 거리감과 쉽게 설명하기 어려운 감정은 인물들의 행동과 시선을 따라가며 천천히 드러난다. 작품은 누군가를 완전히 이해한다는 것이 얼마나 어려운 일인지, 그리고 서로 다른 삶을 살아온 사람들이 관계를 이어 간다는 것이 어떤 의미를 갖는지를 차분하게 바라본다. 특별하지 않은 순간처럼 보이는 장면에도 인물의 내면과 관계의 변화가 스며들어 있으며, 독자는 이야기의 흐름을 따라가면서 그 안에 감춰진 감정의 움직임을 발견하게 된다. 『호아』는 삶에서 쉽게 지나칠 수 있는 감정과 관계의 순간을 섬세하게 들여다보며, 타인과 함께 살아간다는 것의 의미를 생각하게 하는 작품이다.
    `,
    editorReview: `
      『호아』의 매력은 인물의 감정을 직접적으로 설명하기보다 관계 속에서 자연스럽게 드러나는 말과 행동을 통해 보여 준다는 데 있다. 사람 사이의 감정은 언제나 명확한 언어로 표현되지 않으며, 오히려 아무렇지 않게 건넨 말이나 잠시 머뭇거리는 행동 속에서 더 선명하게 드러나기도 한다. 작품은 이러한 미세한 감정의 움직임을 따라가며 인물들이 서로에게 어떤 존재가 되어 가는지를 세심하게 바라본다.

      이야기 속 인물들은 완벽하게 서로를 이해하지 못하고 때로는 자신의 마음조차 정확하게 설명하지 못한다. 그럼에도 관계를 계속 이어 가고 상대방의 마음을 헤아리려는 과정 속에서 삶의 여러 모습이 드러난다. 이 작품에서 관계는 단순히 친밀하거나 멀어지는 것으로 나뉘지 않고, 시간과 상황에 따라 계속 변화하는 것으로 표현된다. 이러한 섬세한 시선은 독자로 하여금 자신의 경험 속에서 지나쳤던 관계와 감정을 다시 떠올리게 한다. 『호아』는 크고 극적인 사건보다 일상의 작은 변화에 집중하면서 사람과 사람 사이에 존재하는 복잡하고 미묘한 감정을 차분하게 보여 주는 작품이다.
    `,
    authorInfo: `
      강진아는 한국문학을 기반으로 작품 활동을 이어 가는 소설가이다. 일상에서 발생하는 관계의 변화와 인물의 내면을 세심하게 관찰하며, 크고 극적인 사건보다는 삶의 구체적인 순간에서 발생하는 감정과 갈등을 작품 속에 담아내는 방식으로 이야기를 만들어 간다.

      그의 작품에서 인물들은 일상적인 관계 속에서 자신과 타인의 마음을 마주하며 변화한다. 가까운 사람 사이에서 발생하는 오해와 거리감, 쉽게 말로 표현하기 어려운 감정 등을 섬세하게 포착하면서 개인의 삶과 관계를 바라보는 시선을 보여 준다. 특히 인물의 감정을 단정적으로 설명하기보다 대화와 행동, 주변의 분위기를 통해 독자가 직접 감정을 읽어 낼 수 있도록 하는 것이 작품의 특징으로 볼 수 있다.

      『호아』 역시 이러한 관심을 바탕으로 인간관계와 일상의 감정을 세밀하게 들여다보는 작품이다. 평범한 삶 속에서 발생하는 작은 변화에 주목하면서 타인을 이해하는 일의 어려움과 관계를 이어 가는 과정에서 생겨나는 다양한 감정을 보여 준다.
    `
