    oneLineIntro: `재난 앞에서 인간은 무엇을 선택하는가`,
    aiReviewTitle: `재난 속에서 드러나는 인간의 연대와 책임`,
    aiReviewContent: `『페스트』는 갑작스러운 전염병으로 봉쇄된 도시 오랑에서 각자의 방식으로 위기에 대응하는 사람들을 통해 부조리와 연대를 탐구하는 카뮈의 걸작입니다. 의사 리외의 담담한 헌신이 깊은 울림을 주며, 재난 앞에서 인간이 무엇을 선택할 수 있는지를 진지하게 묻습니다. 시대를 초월한 통찰을 지닌 작품을 찾는 독자에게 권합니다.`,
    description: `
      알베르 카뮈의 『페스트』는 알제리의 도시 오랑에 갑작스럽게 전염병이 퍼지면서 평범했던 도시의 일상이 무너지는 과정을 그린 소설이다. 처음에는 원인을 알 수 없는 죽은 쥐들이 도시 곳곳에서 발견되고 사람들이 하나둘 병에 걸리기 시작하지만, 사람들은 자신들의 일상이 바뀔 것이라는 사실을 쉽게 받아들이지 못한다. 결국 도시가 봉쇄되고 사람들은 가족과 연인, 친구와 떨어진 채 외부와 단절된 생활을 이어 가게 된다. 의사 리외를 비롯한 여러 인물은 각자의 방식으로 전염병에 맞서며 고통받는 사람들을 돕는다. 누군가는 자신의 의무라고 생각해서 행동하고, 누군가는 종교적 의미를 찾으며, 또 다른 사람은 개인적인 목적을 위해 움직인다. 서로 다른 가치관을 가진 사람들이 재난이라는 공통의 현실 앞에서 함께 살아가는 모습은 인간의 연대와 책임에 대한 질문으로 이어진다. 카뮈는 전염병이라는 극단적인 상황을 통해 인간이 예측할 수 없는 고통과 부조리에 어떻게 대응할 수 있는지를 보여 준다. 『페스트』는 질병 자체에 대한 이야기를 넘어 재난과 죽음 앞에서 타인을 외면하지 않고 자신의 자리에서 행동하는 인간의 모습을 그린 작품이며, 평범한 일상이 얼마나 소중한 것인지 돌아보게 한다.
    `,
    editorReview: `
      『페스트』에서 전염병은 도시 전체의 삶을 뒤흔드는 거대한 사건이지만, 카뮈가 집중하는 것은 재난 자체보다 그 상황에 놓인 사람들이 어떤 선택을 하는가이다. 평소에는 서로 다른 삶을 살아가던 사람들이 도시가 봉쇄되면서 동일한 위기 안에 놓이고, 각자는 자신의 가치관에 따라 상황을 받아들인다. 누군가는 현실을 부정하고, 누군가는 자신의 이익을 우선하며, 또 누군가는 다른 사람을 돕기 위해 위험을 감수한다. 이러한 다양한 인물들의 모습은 재난 속에서 인간의 태도가 얼마나 복잡하게 나타나는지를 보여 준다.

      특히 의사 리외의 행동은 작품의 중요한 축을 이룬다. 그는 자신이 모든 것을 해결할 수 있다고 믿지 않으며 전염병을 완전히 없애겠다는 거창한 목표보다 눈앞에서 고통받는 사람들을 치료하는 일을 계속한다. 이러한 태도는 인간이 모든 고통을 없앨 수는 없더라도 자신이 할 수 있는 일을 선택할 수 있다는 작품의 핵심적인 문제의식과 연결된다. 다른 인물들 역시 각자의 방식으로 페스트에 대응하면서 개인의 삶과 타인에 대한 책임 사이에서 선택하게 된다.

      카뮈는 재난이 언제든 다시 찾아올 수 있다는 가능성을 남겨 둠으로써 이야기를 특정한 사건에만 한정하지 않는다. 페스트가 사라진 뒤에도 사람들은 이전과 완전히 같은 삶으로 돌아갈 수 없으며, 언제든 다시 위기가 찾아올 수 있다는 사실을 기억하게 된다. 『페스트』는 이러한 불확실성 속에서 인간이 서로에게 어떤 존재가 될 수 있는지 질문하며, 연대와 책임이라는 가치를 문학적으로 탐구하는 작품이다.
    `,
    authorInfo: `
      알베르 카뮈는 1913년 프랑스령 알제리에서 태어난 작가이자 사상가이다. 알제리에서 성장한 뒤 알제 대학교에서 철학을 공부했으며 기자와 작가로 활동했다. 제2차 세계대전 당시에는 프랑스 레지스탕스의 지하 신문인 《콩바》의 편집에 참여했으며, 전쟁 이후 소설과 에세이, 희곡 등을 발표하면서 프랑스 문학과 사상계에서 중요한 작가로 자리 잡았다.

      『페스트』는 1947년에 발표된 대표적인 장편소설로, 알제리의 오랑을 배경으로 전염병이 도시 전체로 확산되는 과정을 다룬다. 작품은 재난 속에서 인간이 어떻게 행동하는지를 보여 주면서 연대와 책임, 부조리한 세계에 대응하는 인간의 태도를 탐구한다. 카뮈는 전염병이라는 구체적인 사건을 통해 인간이 통제할 수 없는 고통과 죽음을 마주하는 상황을 문학적으로 표현했다.

      카뮈는 『이방인』, 『시지프 신화』, 『반항하는 인간』, 『전락』 등 다양한 작품을 통해 인간의 존재와 부조리, 자유와 책임에 대한 문제를 지속적으로 다루었다. 그의 작품에서 인간은 세계에 절대적인 의미가 존재하지 않는다는 사실과 마주하면서도 자신의 삶과 타인에 대한 책임을 포기하지 않는 존재로 그려진다. 이러한 문학적 성취를 인정받아 1957년 노벨 문학상을 수상했으며, 1960년 프랑스에서 자동차 사고로 세상을 떠났다.
    `
